INSERT IGNORE INTO `autoexec_customtemplate` VALUES (827472484507648, 'k8s发布面板', 1, '<div id=\"app\">\n  <Divider orientation=\"start\">Deployment</Divider>\n  <Row v-if=\"k8s_data && k8s_data.deployment && k8s_data.deployment.objectMeta\" class=\"pb-nm\">\n    <Col span=\"4\">\n    <div class=\"text-title\">名称</div>\n    <div>{{ k8s_data.deployment.objectMeta.name }}</div>\n    </Col>\n    <Col span=\"4\">\n    <div class=\"text-title\">命名空间</div>\n    <div>{{ k8s_data.deployment.objectMeta.namespace }}</div>\n    </Col>\n    <Col span=\"4\">\n    <div class=\"text-title\">创建时间</div>\n    <div>{{ k8s_data.deployment.objectMeta.creationTimestamp | formatDate }}</div>\n    </Col>\n    <Col span=\"8\">\n    <div class=\"text-title\">UID</div>\n    <div>{{ k8s_data.deployment.objectMeta.uid }}</div>\n    </Col>\n	</Row>\n	\n	<div class=\"pb-nm\" v-if=\"k8s_data && k8s_data.deployment && k8s_data.deployment.objectMeta\">\n     <div class=\"pb-sm\">标签</div>\n     <Tag v-for=\"(value, key, index) in k8s_data.deployment.objectMeta.labels\">{{ key }}:{{ value }}</Tag>\n	</div>\n	<div class=\"pb-nm\" v-if=\"k8s_data && k8s_data.deployment && k8s_data.deployment.objectMeta\">\n     <div class=\"pb-sm\">注释</div>\n	 <Tag v-for=\"(value, key, index) in k8s_data.deployment.objectMeta.annotations\">{{ key }}:{{ value }}</Tag> \n	</div>\n	\n	<Divider orientation=\"start\">New ReplicaSet</Divider>\n	<Row v-if=\"k8s_data.newreplicaset && k8s_data.newreplicaset.objectMeta\" class=\"pb-nm\">\n    <Col span=\"4\">\n    <div class=\"text-title\">名称</div>\n    <div>{{ k8s_data.newreplicaset.objectMeta.name }}</div>\n    </Col>\n    <Col span=\"4\">\n    <div class=\"text-title\">命名空间</div>\n    <div>{{ k8s_data.newreplicaset.objectMeta.namespace }}</div>\n    </Col>\n    <Col span=\"4\">\n    <div class=\"text-title\">创建时间</div>\n    <div>{{ k8s_data.newreplicaset.objectMeta.creationTimestamp | formatDate }}</div>\n    </Col>\n    <Col span=\"4\">\n    <div class=\"text-title\">Pods</div>\n    <div>{{k8s_data.newreplicaset.podInfo.desired}}/{{k8s_data.newreplicaset.podInfo.running}}</div>\n    </Col>\n	</Row>\n	\n	<div class=\"pb-nm\" v-if=\"k8s_data.newreplicaset && k8s_data.newreplicaset.objectMeta\">\n     <div class=\"pb-sm\">标签</div>\n     <Tag v-for=\"(value, key, index) in k8s_data.newreplicaset.objectMeta.labels\">{{ key }}:{{ value }}</Tag>\n	</div>\n	<div class=\"pb-nm\" v-if=\"k8s_data.newreplicaset && k8s_data.newreplicaset.objectMeta\">\n     <div class=\"pb-sm\">注释</div>\n	 <Tag v-for=\"(value, key, index) in k8s_data.newreplicaset.objectMeta.annotations\">{{ key }}:{{ value }}</Tag> \n	</div>\n	\n	<Divider orientation=\"start\">Pods</Divider>\n	<TsTable\n    v-if=\"k8s_data.newreplicaset && k8s_data.newreplicaset.pod\"\n    :theadList=\"theadList\"\n    :tbodyList=\"k8s_data.newreplicaset.pod.pods\"\n    :fixedHeader=\"false\"\n     >\n     <template v-slot:name=\"{row}\">\n       <div>{{row.objectMeta.name}}</div>\n     </template>\n      <template v-slot:containerImages=\"{row}\">\n        <Tag v-for=\"(item,index) in row.containerImages\" :key=\"index\">{{ item }}</Tag> \n      </template>\n       <template v-slot:labels=\"{row}\">\n        <Tag v-for=\"(value, key, index) in row.objectMeta.labels\" :key=\"index\">{{ key }}:{{ value }}</Tag> \n      </template>\n      <template v-slot:status=\"{row}\">\n        <div :class=\"row.status==\'Running\'?\'text-success\':\'text-danger\'\">{{ row.status }}</div>\n      </template>\n    </TsTable>\n</div>', '{\n	data(){\n      return{\n      	k8s_data:{}\n      }	\n	},\n   computed:{\n 		theadList(){\n          return [\n            { key: \'name\', title: \'名称\' },\n            { key: \'containerImages\', title: \'镜像\' },\n            { key: \'status\', title: \'状态\' },\n            { key: \'labels\', title: \'标签\' },	\n            { key: \'nodeName\', title: \'节点\' }\n          ];\n        }\n   }\n}', '2023-02-15 16:40:07.733', 'c8dea216f5bd49349db05cbc87db2f9a', '2023-06-27 09:57:35.508', 'c8dea216f5bd49349db05cbc87db2f9a');

