, 933989714870272, '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ci>\n   <!--模型属性定义，需要SQL语句返回对应列-->\n  <attrs>\n    <attr name=\"team_uuid\" label=\"分组uuid\"/>\n    <attr name=\"team_name\" label=\"分组名\"/>\n  </attrs>\n  <sql>\n    SELECT\n    <!--必须包含id字段，作为配置项主键-->\n    `t`.`id` as id,\n    <!--必须包含uuid字段，数据类型是char(32)，作为配置项全局主键-->\n    `uuid` as uuid,\n    <!--必须包含name字段，作为配置项名称-->\n    `t`.`name` AS name,\n    <!--属性列需要在上面attrs中定义才生效-->\n    `t`.`uuid` as team_uuid,\n    `t`.`name` AS team_name\n    FROM\n    `team` `t` \n    where `t`.level = \'department\'\n  </sql>\n</ci>', 0), (480125644709888, 'BusinessGroup', '事业部', NULL, 'tsfont-ci', 482263699349504, 481849293725696, 481849998368768, 457, 458, 0, 0, 0, 0, NULL, NULL, 0), (480157781467136, 'Computer', '服务器', NULL, 'tsfont-storages', 441079476264960, 441090540838912, 479624442159104, 211, 212, 0, 0, 0, 0, NULL, NULL, 0), (480863598731264, 'Vendor', '厂商', NULL, 'tsfont-ci', 482263699349504, 481849293725696, 481849998368768, 459, 460, 0, 0, 0, 0, NULL, NULL, 0), (480864647307264, 'DevelopType', '开发类型', NULL, 'tsfont-ci', 482263699349504, 481849293725696, 481849998368768, 461, 462, 0, 0, 0, 0, NULL, NULL, 0), (481658427727872, 'ExtBasicInfo', '基础信息扩展', NULL, 'tsfont-ci', 441078880673792, NULL, 481659140759552, 234, 445, 0, 0, 1, 0, NULL, NULL, 0), (481849293725696, 'BaseInfo', '基础信息', NULL, 'tsfont-ci', 482263699349504, NULL, 481849998368768, 446, 521, 0, 0, 1, 0, NULL, NULL, 0), (482385359331328, 'ETHInterfaces', '网卡', NULL, 'tsfont-adapter', 482440665423872, 441087512551424, 482386894446592, 227, 228, 0, 0, 0, 0, NULL, NULL, 0), (482390962921472, 'OSPatche', '补丁列表', '集中存放补丁列表', 'tsfont-ci', 482263699349504, 481849293725696, 481849998368768, 463, 464, 0, 0, 0, 0, NULL, NULL, 0), (482391566901248, 'OSUser', '操作系统用户', '操作系统用户', 'tsfont-ci', 482263699349504, 481849293725696, 481849998368768, 465, 466, 0, 0, 0, 0, NULL, NULL, 0), (482395954143232, 'MountPoints', '逻辑磁盘', NULL, 'tsfont-ci', 482440665423872, 4818492