INSERT IGNORE INTO `cmdb_resourcecenter_config` VALUES (1, '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<resourcecenter>\n	<!-- 应用系统 -->\n    <resource id=\"resource_appsystem\" ci=\"APP\">\n        <attr field=\"id\" attr=\"_id\"/>\n        <attr field=\"abbr_name\" attr=\"abbrName\"/>\n        <attr field=\"name\" attr=\"name\"/>\n			<attr field=\"type_id\" attr=\"_typeId\"/>\n			<attr field=\"type_name\" attr=\"_typeName\"/>\n			<attr field=\"type_label\" attr=\"_typeLabel\"/>\n			<attr field=\"fcu\" attr=\"_fcu\"/>\n			<attr field=\"fcd\" attr=\"_fcd\"/>\n			<attr field=\"lcu\" attr=\"_lcu\"/>\n			<attr field=\"lcd\" attr=\"_lcd\"/>\n        <attr field=\"maintenance_window\" attr=\"maintenance_window\"/>\n        <attr field=\"description\" attr=\"description\"/>\n			<attr field=\"inspect_status\" attr=\"_inspectStatus\"/>\n			<attr field=\"inspect_time\" attr=\"_inspectTime\"/>\n			<attr field=\"monitor_status\" attr=\"_monitorStatus\"/>\n			<attr field=\"monitor_time\" attr=\"_monitorTime\"/>\n    </resource>\n\n    <resource id=\"resource_appsystem_state\" ci=\"APP\">\n        <attr field=\"resource_id\" attr=\"_id\"/>\n        <attr field=\"state_name\" ci=\"CIState\" attr=\"name\"/>\n        <attr field=\"state_label\" ci=\"CIState\" attr=\"label\"/>\n        <join>\n            <attr field=\"state_id\" ci=\"CIState\" joinAttrName=\"state\"/>\n        </join>\n    </resource>\n\n    <resource id=\"resource_appsystem_owner\" ci=\"APP\">\n        <attr field=\"resource_id\" attr=\"_id\"/>\n        <attr field=\"user_name\" ci=\"User\" attr=\"user_name\"/>\n        <attr field=\"user_uuid\" ci=\"User\" attr=\"_uuid\"/>\n        <join>\n            <attr field=\"user_id\" ci=\"User\" joinAttrName=\"owner\"/>\n        </join>\n    </resource>\n\n    <resource id=\"resource_appsystem_bg\" ci=\"APP\">\n        <attr field=\"resource_id\" attr=\"_id\"/>\n        <attr field=\"bg_name\" ci=\"BusinessGroup\" attr=\"name\"/>										 \n        <join>\n            <attr field=\"bg_id\" ci=\"BusinessGroup\" joinAttrName=\"business_group\"/>\n        </join>\n    </resource>\n\n    <resource id=\"resource_appsystem_appmodule\" ci=\"APP\">\n        <attr field=\"resource_id\" attr=\"_id\"/>\n        <attr field=\"app_module_abbr_name\" ci=\"APPComponent\" attr=\"abbrName\"/>\n			<attr field=\"app_module_name\" ci=\"APPComponent\" attr=\"name\"/>\n        <join>\n            <rel field=\"app_module_id\" ci=\"APPComponent\"/>\n        </join>\n    </resource>\n\n    <resource id=\"resource_appsystem_productiontimeperiod\" ci=\"APP\">\n        <attr field=\"resource_id\" attr=\"_id\"/>\n        <attr field=\"productiontimeperiod_code\" ci=\"ProductionTimePeriod\" attr=\"code\"/>\n        <attr field=\"productiontimeperiod_label\" ci=\"ProductionTimePeriod\" attr=\"label\"/>\n        <join>\n            <attr field=\"productiontimeperiod_id\" ci=\"ProductionTimePeriod\" joinAttrName=\"productionTimePeriod\"/>\n        </join>\n    </resource>\n	<!-- 应用模块 -->\n    <resource id=\"resource_appmodule\" ci=\"APPComponent\">\n        <attr field=\"id\" attr=\"_id\"/>\n        <attr field=\"abbr_name\" attr=\"abbrName\"/>\n        <attr field=\"name\" attr=\"name\"/>\n			<attr field=\"type_id\" attr=\"_typeId\"/>\n			<attr field=\"type_name\" attr=\"_typeName\"/>\n			<attr field=\"type_label\" attr=\"_typeLabel\"/>\n			<attr field=\"fcu\" attr=\"_fcu\"/>\n			<attr field=\"fcd\" attr=\"_fcd\"/>\n			<attr field=\"lcu\" attr=\"_lcu\"/>\n			<attr field=\"lcd\" attr=\"_lcd\"/>\n        <attr field=\"maintenance_window\" attr=\"maintenance_window\"/>\n        <attr field=\"description\" attr=\"description\"/>\n			<attr field=\"inspect_status\" attr=\"_inspectStatus\"/>\n			<attr field=\"inspect_time\" attr=\"_inspectTime\"/>\n			<attr field=\"monitor_status\" attr=\"_monitorStatus\"/>\n			<attr field=\"monitor_time\" attr=\"_monitorTime\"/>\n    </resource>\n    <resource id=\"resource_appmodule_appsystem\" ci=\"APPComponent\">\n        <attr fiel